// https://community.spline.design/file/c41c357f-a433-4a13-ad23-398c7541e18f
export async function createScene(engine, canvas, BABYLON) {
  //   console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color3(0, 0, 0);
  scene.useRightHandedSystem = true;
  // scene.environmentIntensity = 1.5;

  scene.enablePhysics(new BABYLON.Vector3(0, -9.81, 0), new BABYLON.CannonJSPlugin());
  var physicsViewer = new BABYLON.PhysicsViewer(scene);

  const camera = new BABYLON.ArcRotateCamera("camera", 0, 1.54, 40, BABYLON.Vector3.Zero(), scene);
  camera.useAutoRotationBehavior = true;
  camera.autoRotationBehavior.idleRotationSpeed = 0.6;
  camera.useFramingBehavior = true;
  camera.framingBehavior.radiusScale = 0.6;

  const light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 1.2;

  const nightHDR = new BABYLON.HDRCubeTexture("https://playground.babylonjs.com/textures/night.hdr", scene, 512);
  const parkingHDR = BABYLON.CubeTexture.CreateFromPrefilteredData("/images/Runyon_Canyon_A_2k_cube_specular.dds", scene);

  scene.environmentTexture = nightHDR;

  const dpp = new BABYLON.DefaultRenderingPipeline("dpp", true, scene, [camera]);
  dpp.bloomEnabled = true;
  dpp.bloomIntensity = 0.6;
  dpp.bloomThreshold = 0.8;
  dpp.bloomKernel = 64;
  dpp.fxaaEnabled = true;
  dpp.sharpenEnabled = true;

  const iridescentMat = new BABYLON.PBRMaterial("iridescentMat", scene);
  iridescentMat.metallic = 1.0;
  iridescentMat.roughness = 0.05;
  iridescentMat.clearCoat.isEnabled = true;
  iridescentMat.clearCoat.intensity = 1.0;
  iridescentMat.iridescence.isEnabled = true;
  iridescentMat.iridescence.intensity = 1.0;
  iridescentMat.iridescence.indexOfRefraction = 1.3;
  iridescentMat.iridescence.minimumThickness = 100;
  iridescentMat.iridescence.maximumThickness = 600;

  iridescentMat.reflectionTexture = scene.environmentTexture;
  iridescentMat.environmentIntensity = 1.2;

  const chainLinks = [];
  const linkHeight = 1.5;
  const linkThickness = 0.5;
  let prevImpostor = null;

  var trs = BABYLON.MeshBuilder.CreateTorus("torus", { diameter: linkHeight, thickness: linkThickness, tessellation: 64 });
  var box = BABYLON.MeshBuilder.CreateBox("box", { size: 2 }, scene);
  trs.position = new BABYLON.Vector3(-1, 0, 0);
  let trsCSG = BABYLON.CSG.FromMesh(trs);
  let boxCSG = BABYLON.CSG.FromMesh(box);
  let shape2 = trsCSG.subtract(boxCSG);
  let arc1 = shape2.toMesh("arc1", iridescentMat, scene);
  let arc2 = shape2.toMesh("arc2", iridescentMat, scene);
  arc2.position.y = -linkHeight;
  trs.dispose();
  box.dispose();

  arc1.rotation.z = -Math.PI / 2;
  arc1.rotation.y = Math.PI / 2;
  arc2.rotation.z = Math.PI / 2;
  arc2.rotation.y = Math.PI / 2;

  var cyl1 = BABYLON.MeshBuilder.CreateCylinder("cylinder1", { height: linkHeight, diameter: linkThickness }, scene);
  cyl1.position.y = -linkHeight / 2;
  cyl1.position.x = -linkThickness * 3.5;
  cyl1.material = iridescentMat;

  var cyl2 = BABYLON.MeshBuilder.CreateCylinder("cylinder2", { height: linkHeight, diameter: linkThickness }, scene);
  cyl2.position.y = -linkHeight / 2;
  cyl2.position.x = -linkThickness * 0.5;
  cyl2.material = iridescentMat;

  var chainMesh = BABYLON.Mesh.MergeMeshes([arc1, arc2, cyl1, cyl2], true, true, undefined, false, true);
  chainMesh.position.x = 1;
  chainMesh.position.y = (linkThickness / 2) * 3;
  chainMesh.bakeCurrentTransformIntoVertices();

  var chainRoot = new BABYLON.Mesh("chainRoot", scene);

  let chains = [];
  let isPhysicsApplied = false;

  for (let i = 10; i > 0; i--) {
    chains[i] = chainMesh.clone(`chain_${i}`);

    const visual = new BABYLON.TransformNode("visual" + i, scene);
    chains[i].parent = visual;

    const box = BABYLON.MeshBuilder.CreateBox("box" + i, {
      width: linkHeight,
      height: linkHeight * 2,
      depth: linkHeight / 2,
    });
    box.visibility = 0;
    box.position.z = (i - 10) * (linkHeight * 2);
    box.rotationQuaternion = null;
    box.rotation = BABYLON.Vector3.Zero();

    visual.parent = box;
    visual.position = BABYLON.Vector3.Zero();

    if (!(i % 2)) {
      chains[i].rotation.y = Math.PI / 2;
    }

    const mass = i === 10 ? 0 : 15;
    box.physicsImpostor = new BABYLON.PhysicsImpostor(
      box,
      BABYLON.PhysicsImpostor.BoxImpostor,
      {
        mass,
        restitution: 0.0,
        friction: 0.9,
      },
      scene
    );

    // physicsViewer.showImpostor(box.physicsImpostor, box);

    if (prevImpostor) {
      const joint = new BABYLON.PhysicsJoint(BABYLON.PhysicsJoint.HingeJoint, {
        mainPivot: new BABYLON.Vector3(0, linkHeight / -2, 0),
        connectedPivot: new BABYLON.Vector3(0, -(-linkHeight - 0.2), 0),
        mainAxis: new BABYLON.Vector3(0, 0, 1),
        connectedAxis: new BABYLON.Vector3(0, 0, 1),
      });

      prevImpostor.addJoint(box.physicsImpostor, joint);
    }

    prevImpostor = box.physicsImpostor;
    chainLinks.push(chains[i]);
  }

  scene.onAfterPhysicsObservable.addOnce(() => {
    scene.meshes.forEach((mesh) => {
      if (mesh.physicsImpostor) {
        mesh.physicsImpostor.sleep();

        const chainMesh = mesh.getChildMeshes(false, (m) => m instanceof BABYLON.Mesh)[0];
        if (chainMesh) {
          const nameOrder = Number(chainMesh.name.replace("chain_", ""));
          if (nameOrder % 2 !== 0) {
            chainMesh.rotation.x = Math.PI / 4;
            chainMesh.position.y = (-linkHeight - 0.3) * (10 - nameOrder);
            chainMesh.position.z = (linkHeight - 0.3) * (10 - nameOrder);
          } else {
            chainMesh.rotation.z = Math.PI / 4;
            chainMesh.position.y = (-linkHeight - 0.3) * (10 - nameOrder);
            chainMesh.position.z = (linkHeight - 0.3) * (10 - nameOrder);
          }
        }
      }
    });
  });

  const originalParents = new Map();

  scene.meshes.forEach((m) => {
    if (m.name.startsWith("chain_")) {
      originalParents.set(m, m.parent);
      m.setParent(chainRoot);
    }
  });

  let childMeshes = chainRoot.getChildMeshes();

  let min = childMeshes[0].getBoundingInfo().boundingBox.minimumWorld;
  let max = childMeshes[0].getBoundingInfo().boundingBox.maximumWorld;

  for (let i = 0; i < childMeshes.length; i++) {
    let meshMin = childMeshes[i].getBoundingInfo().boundingBox.minimumWorld;
    let meshMax = childMeshes[i].getBoundingInfo().boundingBox.maximumWorld;

    min = BABYLON.Vector3.Minimize(min, meshMin);
    max = BABYLON.Vector3.Maximize(max, meshMax);
  }

  chainRoot.setBoundingInfo(new BABYLON.BoundingInfo(min, max));
  chainRoot.rotation.x = -Math.PI / 4;
  chainRoot.position.y = 1;
  camera.setTarget(chainRoot, true);

  chainMesh.dispose();

  originalParents.forEach((parent, mesh) => {
    mesh.setParent(parent);
  });

  setTimeout(() => {
    chainRoot.dispose();
  }, 1000);

  const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  const button = BABYLON.GUI.Button.CreateSimpleButton("btn", "Activate Chain Physics");
  button.width = "220px";
  button.height = "40px";
  button.color = "white";
  button.background = "black";
  button.top = "-40px";
  button.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_BOTTOM;

  button.onPointerUpObservable.add(() => {
    if (isPhysicsApplied) return;

    scene.onAfterPhysicsObservable.addOnce(() => {
      scene.meshes.forEach((mesh) => {
        if (mesh.physicsImpostor) {
          const chainMesh = mesh.getChildMeshes(false, (m) => m instanceof BABYLON.Mesh)[0];
          if (chainMesh) {
            if (chainMesh.name === "chain_10") {
              camera.framingBehavior.radiusScale = 7;
              const target = new BABYLON.Mesh("target", scene);
              target.position = chainMesh.absolutePosition.add(new BABYLON.Vector3(0, -7, 0));
              target.setBoundingInfo(chainMesh.getBoundingInfo());

              camera.setTarget(target, true);

              target.dispose();
            }

            chainMesh.position = BABYLON.Vector3.Zero();

            const nameOrder = Number(chainMesh.name.replace("chain_", ""));
            if (nameOrder % 2 !== 0) {
              chainMesh.rotation.x = 0;
            } else {
              chainMesh.rotation.z = 0;
            }
          }
          mesh.physicsImpostor.wakeUp();

          scene.environmentTexture = parkingHDR;
          iridescentMat.reflectionTexture = scene.environmentTexture;

          dpp.chromaticAberrationEnabled = true;
          dpp.chromaticAberration.aberrationAmount = 5;

          if (mesh.name === "box3") {
            const color1 = new BABYLON.Color3(0.91, 0.49, 0.21).toHexString();
            const color2 = new BABYLON.Color3(0.25, 0.05, 0.47).toHexString();

            var rect1 = new BABYLON.GUI.Rectangle();
            rect1.width = "150px";
            rect1.height = "40px";
            rect1.cornerRadius = 20;
            rect1.color = color1;
            rect1.thickness = 4;
            rect1.background = color2;
            advancedTexture.addControl(rect1);
            rect1.linkWithMesh(mesh);
            rect1.linkOffsetY = -100;
            rect1.linkOffsetX = 80;
            rect1.zIndex = 1;

            var label = new BABYLON.GUI.TextBlock();
            label.text = "Drag me";
            rect1.addControl(label);

            var target = new BABYLON.GUI.Ellipse();
            target.width = "20px";
            target.height = "20px";
            target.color = color1;
            target.thickness = 4;
            target.background = color2;
            target.zIndex = 1;
            advancedTexture.addControl(target);
            target.linkWithMesh(mesh);

            var line = new BABYLON.GUI.Line();
            line.lineWidth = 4;
            line.color = color1;
            line.y2 = 15;
            line.linkOffsetY = -5;
            advancedTexture.addControl(line);
            line.linkWithMesh(mesh);
            line.connectedControl = rect1;

            // pbrMat.emissiveColor = new BABYLON.Color3(0.35, 0.36, 0.94);

            const pbrMat = new BABYLON.PBRMaterial("pbr", scene);
            pbrMat.emissiveColor = new BABYLON.Color3(0.98, 0.76, 0.17);
            const chain = mesh.getChildMeshes(false, (m) => m instanceof BABYLON.Mesh)[0];
            if (chain) {
              chain.material = pbrMat;

              mesh.actionManager = new BABYLON.ActionManager(scene);
              mesh.actionManager.registerAction(
                new BABYLON.SetValueAction(
                  BABYLON.ActionManager.OnPointerOverTrigger,
                  chain.material,
                  "emissiveColor",
                  new BABYLON.Color3(1, 0.02, 0.02)
                )
              );
              mesh.actionManager.registerAction(
                new BABYLON.SetValueAction(
                  BABYLON.ActionManager.OnPointerOutTrigger,
                  chain.material,
                  "emissiveColor",
                  new BABYLON.Color3(0.98, 0.76, 0.17)
                )
              );

              const dragBehavior = new BABYLON.PointerDragBehavior({ dragPlaneNormal: new BABYLON.Vector3(0, 1, 0) });
              dragBehavior.useObjectOrientationForDragging = false;
              mesh.addBehavior(dragBehavior);

              dragBehavior.onDragObservable.add((eventData) => {
                if (eventData?.dragDelta && mesh.physicsImpostor) {
                  mesh.physicsImpostor.setDeltaPosition(eventData.dragDelta);
                  mesh.physicsImpostor.forceUpdate();
                }
              });
            }
          }
        }
      });
    });

    isPhysicsApplied = true;
  });

  advancedTexture.addControl(button);

  return scene;
}
